def is_notebook():
    """Return True if running in a Jupyter/IPython notebook, False otherwise."""
    try:
        from IPython import get_ipython
        shell = get_ipython()
        if shell is None:
            return False
        shell_class = shell.__class__.__name__
        return shell_class == 'ZMQInteractiveShell'
